mapper.select:
select ti.*, ts.* from track_info ti left join (select track_id, MAX(if(stat_type = '0701', stat_num, 0)) as play_stat_num, MAX(if(stat_type = '0702', stat_num, 0)) as collect_stat_num, MAX(if(stat_type = '0703', stat_num, 0)) as praise_stat_num, MAX(if(stat_type = '0704', stat_num, 0)) as comment_stat_num from track_stat where is_deleted = 0 group by track_id) ts on ti.id = ts.track_id
ti.is_deleted = 0 and ti.user_id = #{query.userId} and ti.status = #{query.status} and ti.track_title = #{query.trackTitle}
order by ti.id desc
